package br.com.brindespro.admin;
import br.com.brindespro.catalog.*;import br.com.brindespro.quote.*;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final AdminService service;private final ProductRepository products;public AdminController(AdminService service,ProductRepository products){this.service=service;this.products=products;}@GetMapping("/dashboard") public AdminService.Dashboard dashboard(){return service.dashboard();}@GetMapping("/reports") public AdminService.Dashboard reports(@RequestParam(defaultValue="30") int days){return service.report(days);}@GetMapping("/products") public List<CatalogController.ProductDto> products(){return products.findAll().stream().map(CatalogController::dto).toList();}@PostMapping("/products") public CatalogController.ProductDto create(@RequestBody AdminService.ProductInput input,Authentication auth){return service.saveProduct(null,input,auth.getName());}@PutMapping("/products/{id}") public CatalogController.ProductDto update(@PathVariable Long id,@RequestBody AdminService.ProductInput input,Authentication auth){return service.saveProduct(id,input,auth.getName());}@PutMapping("/products/{id}/tiers") public List<CatalogController.TierDto> tiers(@PathVariable Long id,@RequestBody List<AdminService.TierInput> input,Authentication auth){return service.saveTiers(id,input,auth.getName());}@GetMapping("/quotes") public List<QuoteService.QuoteDto> quotes(@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String from,@RequestParam(defaultValue="") String to){return service.quotes(search,status,from,to);}@PatchMapping("/quotes/{id}") public QuoteService.QuoteDto updateQuote(@PathVariable Long id,@RequestBody StatusInput input,Authentication auth){return service.updateQuote(id,input.status(),input.note(),auth.getName());}@GetMapping("/quotes/{id}/history") public List<AuditLog> history(@PathVariable Long id){return service.history(id);}public record StatusInput(String status,String note){} }

